using System;
using System.Drawing;
using System.Windows.Forms;
namespace ImageNdi {
public partial class MainWindow {
 readonly CheckBox videoLoop=new CheckBox{Name="VideoLoop",Text="Loop video",AutoSize=true,Enabled=false};
 readonly Label videoStatus=new Label{Name="VideoStatus",AutoSize=true};
 VideoSession selectionVideo;long selectionVideoSequence;bool videoPending;DateTime videoDue;
 double SpeedFor(string path){double value;return path!=null&&settings.VideoSpeeds.TryGetValue(path,out value)?value:1;}
 void InitializeVideo(Control bar){bar.Height=100;var row=new FlowLayoutPanel{Name="VideoControls",Width=1000,Height=34,AutoScroll=true};bar.Controls.Add(row);row.Controls.Add(videoLoop);row.Controls.Add(videoStatus);videoLoop.CheckedChanged+=delegate{if(!loading&&VideoTools.IsVideo(selected))ApplyPlacement(PlacementNow(),true);};preview.PlayPauseRequested+=delegate{ToggleVideo(false);};program.PlayPauseRequested+=delegate{ToggleVideo(true);};preview.RestartRequested+=delegate{RestartVideo(false,null);};program.RestartRequested+=delegate{RestartVideo(true,null);};preview.VideoSpeedChanged+=delegate{RestartVideo(false,preview.VideoSpeed);};program.VideoSpeedChanged+=delegate{RestartVideo(true,program.VideoSpeed);};Disposed+=delegate{StopSelectionVideo();};}
 void StopSelectionVideo(){videoPending=false;if(selectionVideo!=null){selectionVideo.Dispose();selectionVideo=null;}selectionVideoSequence=0;preview.SetVideoTransport(null);}
 void ScheduleSelectionVideo(){videoLoop.Enabled=VideoTools.IsVideo(selected);if(videoLoop.Enabled&&pending!=null){videoPending=true;videoDue=DateTime.UtcNow.AddMilliseconds(150);}}
 void StartSelectionVideo(){StopSelectionVideo();videoLoop.Enabled=VideoTools.IsVideo(selected);if(!videoLoop.Enabled||pending==null)return;selectionVideo=new VideoSession(selected,FrameWidth,FrameHeight,output==null?previewOutput==null?(int)fps.Value:previewFps:activeProgramFps,PlacementNow(),videoLoop.Checked,pending,PreviewAudio,GainFor(selected),SpeedFor(selected));selectionVideo.ActivateAudio(0);PublishPreview();preview.SetVideoTransport(selectionVideo);}
 void ToggleVideo(bool onProgram){var video=onProgram?(output==null?null:output.CurrentVideo):selectionVideo;if(video==null)return;if(video.Ended&&!video.Paused){RestartVideo(onProgram,null);return;}video.SetPaused(!video.Paused);(onProgram?program:preview).SetVideoTransport(video);}
 void RestartVideo(bool onProgram,double? newSpeed){var video=onProgram?(output==null?null:output.CurrentVideo):selectionVideo;if(video==null)return;VideoSession replacement=null;bool adopted=false;try{if(newSpeed.HasValue){if(onProgram)muteProgram.Checked=true;else mutePreview.Checked=true;}double speed=newSpeed??video.Speed;replacement=video.Restart(speed,video.Paused,GainFor(video.Path));if(onProgram){output.CueSource(replacement,replacement.ReadFrame(),0,video.Path);adopted=true;}else{replacement.ActivateAudio(0);selectionVideo=replacement;adopted=true;selectionVideoSequence=0;video.Dispose();pending=replacement.ReadFrame();preview.SetFrame(Renderer.ToBitmap(pending,FrameWidth,FrameHeight),FrameWidth,FrameHeight);PublishPreview();}if(newSpeed.HasValue){settings.VideoSpeeds[replacement.Path]=speed;Save();}(onProgram?program:preview).SetVideoTransport(replacement);}catch(Exception e){status.Text="Controllo video: "+e.Message;MessageBox.Show(e.Message,"Controllo video");(onProgram?program:preview).SetVideoTransport(onProgram?(output==null?null:output.CurrentVideo):selectionVideo);}finally{if(!adopted&&replacement!=null)replacement.Dispose();}}
 void UpdateSelectionVideo(){program.SetVideoTransport(output==null?null:output.CurrentVideo);if(videoPending&&DateTime.UtcNow>=videoDue){try{StartSelectionVideo();}catch(Exception e){videoStatus.Text=e.Message;return;}}if(selectionVideo==null){videoStatus.Text="";return;}preview.SetVideoTransport(selectionVideo);videoStatus.Text=selectionVideo.Error??(selectionVideo.Ended?"Video terminato · ultimo fotogramma":selectionVideo.Paused?"Video in pausa":videoLoop.Checked?"Video in loop · "+(PreviewAudio==null?"audio Preview spento":"audio Preview abilitato"):"Video in riproduzione · "+(PreviewAudio==null?"audio Preview spento":"audio Preview abilitato"));long sequence=System.Threading.Interlocked.Read(ref selectionVideo.DecodedFrames);if(sequence==selectionVideoSequence)return;selectionVideoSequence=sequence;pending=selectionVideo.ReadFrame();preview.SetFrame(Renderer.ToBitmap(pending,FrameWidth,FrameHeight),FrameWidth,FrameHeight);}
}
}
